package net.earthcomputer.clientcommands.command;

import com.mojang.brigadier.CommandDispatcher;
import com.mojang.brigadier.arguments.StringArgumentType;
import net.earthcomputer.clientcommands.Configs;
import net.earthcomputer.clientcommands.platform.CClientCommandSource;
import net.minecraft.ChatFormatting;
import net.minecraft.commands.SharedSuggestionProvider;
import net.minecraft.network.chat.Component;

import java.util.List;

import static net.earthcomputer.clientcommands.compat.ClientCommands.*;

/**
 * Native replacement for the option command generated by the removed config library.
 *
 * <pre>
 * /cconfig                      list every option and its value
 * /cconfig get &lt;option&gt;         print one value
 * /cconfig set &lt;option&gt; &lt;value&gt; change a value and save the config
 * </pre>
 */
public final class ConfigCommand {
    private ConfigCommand() {
    }

    public static void register(CommandDispatcher<CClientCommandSource> dispatcher) {
        dispatcher.register(literal("cconfig")
            .executes(ctx -> list(ctx.getSource()))
            .then(literal("list")
                .executes(ctx -> list(ctx.getSource())))
            .then(literal("get")
                .then(argument("option", StringArgumentType.word())
                    .suggests((ctx, builder) -> SharedSuggestionProvider.suggest(Configs.getOptionNames(), builder))
                    .executes(ctx -> get(ctx.getSource(), StringArgumentType.getString(ctx, "option")))))
            .then(literal("set")
                .then(argument("option", StringArgumentType.word())
                    .suggests((ctx, builder) -> SharedSuggestionProvider.suggest(Configs.getOptionNames(), builder))
                    .then(argument("value", StringArgumentType.greedyString())
                        .executes(ctx -> set(ctx.getSource(),
                            StringArgumentType.getString(ctx, "option"),
                            StringArgumentType.getString(ctx, "value")))))));
    }

    private static int list(CClientCommandSource source) {
        List<String> names = Configs.getOptionNames();
        source.sendFeedback(Component.literal("clientcommands options (" + names.size() + "):"));
        for (String name : names) {
            source.sendFeedback(Component.literal("  " + name + " = " + Configs.getOptionValue(name)).withStyle(ChatFormatting.GRAY));
        }
        return names.size();
    }

    private static int get(CClientCommandSource source, String option) {
        String value = Configs.getOptionValue(option);
        if (value == null) {
            source.sendError(Component.literal("Unknown option: " + option));
            return 0;
        }
        source.sendFeedback(Component.literal(option + " = " + value));
        return 1;
    }

    private static int set(CClientCommandSource source, String option, String value) {
        String error = Configs.setOptionValue(option, value);
        if (error != null) {
            source.sendError(Component.literal(error));
            return 0;
        }
        source.sendFeedback(Component.literal(option + " = " + Configs.getOptionValue(option)));
        return 1;
    }
}
